{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `goodtribe-wh.maplemonk.goodtribe_dead_weight_master` AS WITH single_sku_single_unit_awbs AS ( SELECT UPPER(TRIM(awb)) AS awb, UPPER(TRIM(MAX(sku))) AS sku_code FROM `goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated` WHERE awb IS NOT NULL AND TRIM(awb) != \'\' AND sku IS NOT NULL AND TRIM(sku) != \'\' GROUP BY UPPER(TRIM(awb)) HAVING SUM(IFNULL(quantity, 0)) = 1 AND COUNT(DISTINCT UPPER(TRIM(sku))) = 1 ), awb_weights AS ( SELECT UPPER(TRIM(b.cawbno)) AS cawbno_clean, s.sku_code, MAX(SAFE_CAST(b.nactwgt AS FLOAT64)) AS nactwgt, MAX(SAFE_CAST(b.nchrgwt AS FLOAT64)) AS nchrgwt FROM `goodtribe-wh.maplemonk.s3_bluedart_freight_logistics_cost` b INNER JOIN single_sku_single_unit_awbs s ON UPPER(TRIM(b.cawbno)) = s.awb WHERE b.cawbno IS NOT NULL AND SAFE_CAST(b.nactwgt AS FLOAT64) IS NOT NULL AND SAFE_CAST(b.nactwgt AS FLOAT64) > 0 GROUP BY UPPER(TRIM(b.cawbno)), s.sku_code ) SELECT SPLIT(sku_code, \'-\')[OFFSET(0)] AS style, MIN(nactwgt) AS baseline_net_actual_weight_kg, MIN(nchrgwt) AS minimum_charged_weight_kg, ROUND(AVG(nactwgt), 3) AS average_observed_weight_kg, COUNT(DISTINCT cawbno_clean) AS total_single_unit_sample_count FROM awb_weights GROUP BY style ORDER BY style ASC; CREATE OR REPLACE TABLE `goodtribe-wh.maplemonk.delhivery_rate_card` ( shipment_type STRING, zone_code STRING, first_500g_rate NUMERIC, add_500g_rate NUMERIC ); INSERT INTO `goodtribe-wh.maplemonk.delhivery_rate_card` (shipment_type, zone_code, first_500g_rate, add_500g_rate) VALUES (\'FORWARD\', \'A\', 19.00, 19.00), (\'FORWARD\', \'B\', 22.00, 21.00), (\'FORWARD\', \'C\', 28.00, 25.00), (\'FORWARD\', \'D\', 31.00, 28.00), (\'FORWARD\', \'E\', 39.00, 33.00), (\'FORWARD\', \'F\', 41.00, 35.00), (\'RTO\', \'A\', 19.00, 19.00), (\'RTO\', \'B\', 22.00, 21.00), (\'RTO\', \'C\', 28.00, 25.00), (\'RTO\', \'D\', 31.00, 28.00), (\'RTO\', \'E\', 42.00, 68.00), (\'RTO\', \'F\', 46.00, 71.00), (\'DTO\', \'A\', 35.00, 60.00), (\'DTO\', \'B\', 40.00, 70.00), (\'DTO\', \'C\', 52.00, 90.00), (\'DTO\', \'D\', 61.00, 98.00), (\'DTO\', \'E\', 68.00, 111.00), (\'DTO\', \'F\', 74.00, 116.00); CREATE OR REPLACE TABLE `goodtribe-wh.maplemonk.bluedart_rate_card` ( product_type STRING, zone_code STRING, first_500g_rate NUMERIC, add_500g_rate NUMERIC ); INSERT INTO `goodtribe-wh.maplemonk.bluedart_rate_card` (product_type, zone_code, first_500g_rate, add_500g_rate) VALUES (\'Ecom Air\', \'Intra City\', 20.00, 20.00), (\'Ecom Air\', \'Intra Region\', 23.00, 23.00), (\'Ecom Air\', \'Metro\', 30.00, 29.00), (\'Ecom Air\', \'All India\', 34.00, 30.00), (\'Ecom Air\', \'NE/JK\', 45.00, 30.00), (\'Ecom Air\', \'A\', 20.00, 20.00), (\'Ecom Air\', \'B\', 23.00, 23.00), (\'Ecom Air\', \'C\', 30.00, 29.00), (\'Ecom Air\', \'D\', 34.00, 30.00), (\'Ecom Air\', \'E\', 45.00, 30.00), (\'eCom Lite Surface\', \'Intra City\', 17.00, 16.00), (\'eCom Lite Surface\', \'Intra Region\', 19.00, 17.00), (\'eCom Lite Surface\', \'Metro\', 24.00, 22.00), (\'eCom Lite Surface\', \'All India\', 26.00, 23.00), (\'eCom Lite Surface\', \'NE/JK\', 33.00, 32.00), (\'eCom Lite Surface\', \'A\', 17.00, 16.00), (\'eCom Lite Surface\', \'B\', 19.00, 17.00), (\'eCom Lite Surface\', \'C\', 24.00, 22.00), (\'eCom Lite Surface\', \'D\', 26.00, 23.00), (\'eCom Lite Surface\', \'E\', 33.00, 32.00); CREATE OR REPLACE TABLE `goodtribe-wh.maplemonk.goodtribe_sku_weight_master` AS SELECT COALESCE(d.style, UPPER(TRIM(sku))) AS sku, CAST(d.baseline_net_actual_weight_kg AS FLOAT64) AS dead_weight_kg, CAST(v.volumetric_weight AS FLOAT64) AS volumetric_weight_kg, GREATEST(CAST(d.baseline_net_actual_weight_kg AS FLOAT64), CAST(v.volumetric_weight AS FLOAT64)) AS item_billing_weight_kg FROM `goodtribe-wh.maplemonk.goodtribe_dead_weight_master` d FULL OUTER JOIN ( SELECT * FROM `goodtribe-wh.maplemonk.gs_style_volumeric_weight` QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(sku)) ORDER BY UPPER(TRIM(sku)), UPPER(TRIM(courier)) ASC) = 1 ) v ON UPPER(TRIM(d.style)) = UPPER(TRIM(v.sku)); CREATE OR REPLACE VIEW `goodtribe-wh.maplemonk.goodtribe_logistics_freight_reconciliation` AS WITH all_order_items AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(s.reference_code)), r\'^#\', \'\') AS reference_code, UPPER(TRIM(s.awb)) AS awb, SAFE_CAST(s.order_date AS DATE) AS order_date, s.courier, CAST(s.pincode AS STRING) AS pincode, UPPER(TRIM(s.sku)) AS sku, CAST(s.quantity AS FLOAT64) AS quantity FROM `goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated` s WHERE s.awb IS NOT NULL AND TRIM(s.awb) != \'\' UNION ALL SELECT REGEXP_REPLACE(UPPER(TRIM(r.reference_code)), r\'^#\', \'\') AS reference_code, UPPER(TRIM(r.AWB)) AS awb, r.Order_Date AS order_date, COALESCE(r.Reverse_Carrier_Name, r.Forward_Carrier_Name) AS courier, CAST(NULL AS STRING) AS pincode, UPPER(TRIM(r.SKU)) AS sku, CAST(r.Returned_quantity AS FLOAT64) AS quantity FROM `goodtribe-wh.maplemonk.easyecom_goodtribe_all_returns` r WHERE r.AWB IS NOT NULL AND TRIM(r.AWB) != \'\' ), order_sku_aggregation AS ( SELECT s.reference_code, s.awb, MIN(s.order_date) AS order_date, MAX(c.final_parent_courier) AS courier, MAX(s.pincode) AS order_destination_pincode, SUM(COALESCE(w.dead_weight_kg, 0) * s.quantity) AS expected_total_dead_weight_kg, SUM(COALESCE(w.volumetric_weight_kg, 0) * s.quantity) AS expected_total_volumetric_weight_kg, GREATEST( SUM(COALESCE(w.dead_weight_kg, 0) * s.quantity), SUM(COALESCE(w.volumetric_weight_kg, 0) * s.quantity) ) AS expected_billing_weight_kg FROM all_order_items s LEFT JOIN `goodtribe-wh.maplemonk.goodtribe_sku_weight_master` w ON SPLIT(UPPER(TRIM(s.sku)), \'-\')[OFFSET(0)] = UPPER(TRIM(w.sku)) LEFT JOIN ( SELECT * FROM `goodtribe-wh.maplemonk.gs_courier_mapping` QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(courier)) ORDER BY 1 DESC) = 1 ) c ON UPPER(s.courier) = UPPER(c.courier_partner) GROUP BY s.reference_code, s.awb ), billed_shipments AS ( SELECT UPPER(TRIM(cawbno)) AS waybill_num, REGEXP_EXTRACT(UPPER(TRIM(CCRCRDREF)), r\'^(.*?)(?:_|-?(?:RET|EXC)|$)\') AS order_id, DESTPINCODE AS billed_destination_pincode, UPPER(TRIM(CZONE)) AS billed_zone, ROUND(SAFE_CAST(nchrgwt AS FLOAT64), 3) AS billed_weight_kg, CASE WHEN UPPER(TRIM(CPRODCODE)) IN (\'AP\', \'AC\') THEN \'Ecom Air\' WHEN UPPER(TRIM(CPRODCODE)) IN (\'APL\', \'ACL\') THEN \'eCom Lite Surface\' ELSE \'eCom Lite Surface\' END AS product_type, CASE WHEN UPPER(TRIM(CCRCRDREF)) LIKE \'%RET%\' OR UPPER(TRIM(CCRCRDREF)) LIKE \'%EX%\' OR UPPER(status) LIKE \'%DTO%\' THEN \'DTO\' WHEN UPPER(status) LIKE \'%RTO%\' OR SAFE_CAST(frt_rto AS FLOAT64) > 0 THEN \'RTO\' ELSE \'FORWARD\' END AS shipment_type, SAFE_CAST(NFREIGHT AS FLOAT64) AS billed_freight_charge, SAFE_CAST(NFSAMT AS FLOAT64) AS billed_fuel_surcharge_amount, SAFE_CAST(NCAFAMT AS FLOAT64) AS billed_caf_amount, SAFE_CAST(NFODCHRG AS FLOAT64) AS billed_cod_charge, SAFE_CAST(NIDCCHGS AS FLOAT64) AS billed_idc_charge, SAFE_CAST(NVALCHGS AS FLOAT64) AS billed_value_charge, SAFE_CAST(frt_rto AS FLOAT64) AS billed_rto_charge, 0.0 AS billed_dto_charge, COALESCE(SAFE_CAST(DBA_CHARGE AS FLOAT64), 0.0) AS billed_dba_charge, COALESCE(SAFE_CAST(INTLVAS AS FLOAT64), 0.0) AS billed_intl_vas, COALESCE(SAFE_CAST(OTP_CHARGE AS FLOAT64), 0.0) AS billed_otp_charge, COALESCE(SAFE_CAST(DEMAND_CHARGE AS FLOAT64), 0.0) AS billed_demand_charge, COALESCE(SAFE_CAST(EFSS_CHARGE AS FLOAT64), 0.0) AS billed_efss_charge, COALESCE(SAFE_CAST(CFX_CHARGE AS FLOAT64), 0.0) AS billed_cfx_charge, SAFE_CAST(NTOTAMOUNT AS FLOAT64) AS billed_gross_amount, SAFE_CAST(Net_Amt AS FLOAT64) AS billed_total_amount, \'BLUEDART\' AS courier, SAFE_CAST(ship_date AS DATE) AS shipment_date FROM `goodtribe-wh.maplemonk.s3_bluedart_freight_logistics_cost` UNION ALL SELECT REPLACE(waybill_num, \'=\', \'\') AS waybill_num, REGEXP_EXTRACT(UPPER(TRIM(order_id)), r\'^(.*?)(?:_|-?(?:RET|EXC)|$)\') AS order_id, destination_pin AS billed_destination_pincode, UPPER(TRIM(zone)) AS billed_zone, ROUND(CAST(charged_weight AS FLOAT64) / 1000.0, 3) AS billed_weight_kg, \'STANDARD\' AS product_type, CASE WHEN CAST(charge_DTO AS FLOAT64) > 0 THEN \'DTO\' WHEN CAST(charge_RTO AS FLOAT64) > 0 OR UPPER(status) LIKE \'%RTO%\' THEN \'RTO\' ELSE \'FORWARD\' END AS shipment_type, CAST(charge_DL AS FLOAT64) AS billed_freight_charge, 0.0 AS billed_fuel_surcharge_amount, 0.0 AS billed_caf_amount, 0.0 AS billed_cod_charge, 0.0 AS billed_idc_charge, 0.0 AS billed_value_charge, CAST(charge_RTO AS FLOAT64) AS billed_rto_charge, CAST(charge_DTO AS FLOAT64) AS billed_dto_charge, 0.0 AS billed_dba_charge, 0.0 AS billed_intl_vas, 0.0 AS billed_otp_charge, 0.0 AS billed_demand_charge, 0.0 AS billed_efss_charge, 0.0 AS billed_cfx_charge, CAST(gross_amount AS FLOAT64) AS billed_gross_amount, CAST(total_amount AS FLOAT64) AS billed_total_amount, \'DELHIVERY\' AS courier, SAFE_CAST(NULL AS DATE) AS shipment_date FROM `goodtribe-wh.maplemonk.s3_delhivery_freight_logistics_cost` UNION ALL SELECT REGEXP_REPLACE(TRIM(awb_code), r\"^\'|\'$\", \"\") AS waybill_num, REGEXP_EXTRACT(UPPER(TRIM(order_id)), r\'^(.*?)(?:_|-?(?:RET|EXC)|$)\') AS order_id, CAST(shipping_pincode AS STRING) AS billed_destination_pincode, REGEXP_REPLACE(UPPER(TRIM(zone)), r\'^Z_\', \'\') AS billed_zone, ROUND(SAFE_CAST(charged_weight AS FLOAT64), 3) AS billed_weight_kg, \'STANDARD\' AS product_type, CASE WHEN UPPER(description) LIKE \'%DTO%\' OR UPPER(awb_status) LIKE \'%DTO%\' THEN \'DTO\' WHEN UPPER(description) LIKE \'%RTO%\' OR UPPER(awb_status) LIKE \'%RTO%\' OR SAFE_CAST(rto_charges AS FLOAT64) > 0 THEN \'RTO\' ELSE \'FORWARD\' END AS shipment_type, SAFE_CAST(forward_charges AS FLOAT64) AS billed_freight_charge, 0.0 AS billed_fuel_surcharge_amount, 0.0 AS billed_caf_amount, SAFE_CAST(cod_charges AS FLOAT64) AS billed_cod_charge, 0.0 AS billed_idc_charge, 0.0 AS billed_value_charge, SAFE_CAST(rto_charges AS FLOAT64) AS billed_rto_charge, 0.0 AS billed_dto_charge, 0.0 AS billed_dba_charge, 0.0 AS billed_intl_vas, 0.0 AS billed_otp_charge, 0.0 AS billed_demand_charge, 0.0 AS billed_efss_charge, 0.0 AS billed_cfx_charge, SAFE_CAST(billing_amount__inclusive_gst_ AS FLOAT64) AS billed_gross_amount, SAFE_CAST(billing_amount__inclusive_gst_ AS FLOAT64) AS billed_total_amount, \'SHIPROCKET\' AS courier, SAFE_CAST(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M\', awb_assigned_date) AS DATE) AS shipment_date FROM `goodtribe-wh.maplemonk.s3_shiprocket_freight_logistics_cost` ), pincode_zone_mapping AS ( SELECT pincode, zone, \'DELHIVERY\' AS courier FROM `goodtribe-wh.maplemonk.gs_delhivery_pincode_zone_mapping` QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(pincode) ORDER BY 1) = 1 UNION ALL SELECT cpincode AS pincode, zone, \'BLUEDART\' AS courier FROM `goodtribe-wh.maplemonk.gs_bluedart_pincode_zone_mapping` QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(cpincode) ORDER BY 1) = 1 UNION ALL SELECT TRIM(delivery_pincode) AS pincode, UPPER(TRIM(zone)) AS zone, \'SHIPROCKET\' AS courier FROM `goodtribe-wh.maplemonk.gs_shiprocket_pincode_zone_mapping` QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(delivery_pincode) ORDER BY 1) = 1 ), order_reconciliation_base AS ( SELECT COALESCE(o.awb, b.waybill_num) AS waybill_num, COALESCE(o.reference_code, b.order_id) AS order_id, o.order_date, COALESCE(b.courier, o.courier) AS courier, COALESCE(b.product_type, \'eCom Lite Surface\') AS product_type, COALESCE(b.shipment_type, \'FORWARD\') AS shipment_type, b.shipment_date, \'201301\' AS origin_pincode, COALESCE(o.order_destination_pincode, b.billed_destination_pincode) AS destination_pincode, b.billed_zone, COALESCE(zm.zone, \'D\') AS expected_zone, COALESCE(o.expected_total_dead_weight_kg, 0.0) AS expected_dead_weight_kg, COALESCE(o.expected_total_volumetric_weight_kg, 0.0) AS expected_volumetric_weight_kg, COALESCE(o.expected_billing_weight_kg, 0.5) AS expected_billing_weight_kg, COALESCE(b.billed_weight_kg, 0.0) AS billed_weight_kg, CEIL(COALESCE(o.expected_billing_weight_kg, 0.5) / 0.5) AS expected_weight_slabs_count, CEIL(COALESCE(b.billed_weight_kg, 0.0) / 0.5) AS billed_weight_slabs_count, COALESCE(b.billed_freight_charge, 0.0) AS billed_freight_charge, COALESCE(b.billed_fuel_surcharge_amount, 0.0) AS billed_fuel_surcharge_amount, COALESCE(b.billed_caf_amount, 0.0) AS billed_caf_amount, COALESCE(b.billed_cod_charge, 0.0) AS billed_cod_charge, COALESCE(b.billed_idc_charge, 0.0) AS billed_idc_charge, COALESCE(b.billed_value_charge, 0.0) AS billed_value_charge, COALESCE(b.billed_rto_charge, 0.0) AS billed_rto_charge, COALESCE(b.billed_dto_charge, 0.0) AS billed_dto_charge, COALESCE(b.billed_dba_charge, 0.0) AS billed_dba_charge, COALESCE(b.billed_intl_vas, 0.0) AS billed_intl_vas, COALESCE(b.billed_otp_charge, 0.0) AS billed_otp_charge, COALESCE(b.billed_demand_charge, 0.0) AS billed_demand_charge, COALESCE(b.billed_efss_charge, 0.0) AS billed_efss_charge, COALESCE(b.billed_cfx_charge, 0.0) AS billed_cfx_charge, COALESCE(b.billed_gross_amount, 0.0) AS billed_gross_amount, COALESCE(b.billed_total_amount, 0.0) AS billed_total_amount FROM order_sku_aggregation o FULL OUTER JOIN billed_shipments b ON o.reference_code = b.order_id AND o.awb = b.waybill_num LEFT JOIN pincode_zone_mapping zm ON zm.pincode = COALESCE(o.order_destination_pincode, b.billed_destination_pincode) AND zm.courier = COALESCE(b.courier, o.courier) ), contract_rate_applied AS ( SELECT r.*, CASE WHEN r.courier = \'BLUEDART\' THEN ( COALESCE(bd.first_500g_rate, 26.00) + GREATEST(0, r.expected_weight_slabs_count - 1) * COALESCE(bd.add_500g_rate, 23.00) ) WHEN r.courier = \'SHIPROCKET\' AND r.shipment_date >= \'2026-07-01\' THEN CASE WHEN r.shipment_type = \'FORWARD\' THEN 45.00 WHEN r.shipment_type IN (\'RTO\', \'DTO\') THEN ROUND(45.00 * 1.2, 2) ELSE 45.00 END ELSE ( COALESCE(del.first_500g_rate, 45.00) + GREATEST(0, r.expected_weight_slabs_count - 1) * COALESCE(del.add_500g_rate, 0.00) ) END AS expected_freight_charge FROM order_reconciliation_base r LEFT JOIN `goodtribe-wh.maplemonk.bluedart_rate_card` bd ON r.courier = \'BLUEDART\' AND bd.product_type = r.product_type AND bd.zone_code = r.expected_zone LEFT JOIN `goodtribe-wh.maplemonk.delhivery_rate_card` del ON r.courier = \'DELHIVERY\' AND del.shipment_type = r.shipment_type AND del.zone_code = r.expected_zone ) SELECT waybill_num, order_id, order_date, courier, product_type, shipment_type, shipment_date, origin_pincode, destination_pincode, billed_zone, expected_zone, (billed_zone IS NOT NULL AND expected_zone IS NOT NULL AND billed_zone != expected_zone) AS is_zone_mismatch, expected_dead_weight_kg, expected_volumetric_weight_kg, expected_billing_weight_kg, billed_weight_kg, ROUND(billed_weight_kg - expected_billing_weight_kg, 3) AS weight_discrepancy_kg, (billed_weight_slabs_count > expected_weight_slabs_count) AS is_overweight_charged, billed_freight_charge, expected_freight_charge, ROUND(billed_freight_charge - expected_freight_charge, 2) AS freight_discrepancy_amount, billed_fuel_surcharge_amount, billed_caf_amount, billed_cod_charge, billed_idc_charge, billed_value_charge, (billed_dba_charge + billed_intl_vas + billed_otp_charge + billed_demand_charge + billed_efss_charge + billed_cfx_charge) AS billed_add_on_charges, ROUND(expected_freight_charge * 0.18, 2) AS expected_gst_amount, ROUND(expected_freight_charge * 1.18, 2) AS expected_total_amount, billed_gross_amount, billed_total_amount, ROUND(billed_total_amount - (expected_freight_charge * 1.18), 2) AS total_overcharge_amount, CASE WHEN ROUND(billed_freight_charge - expected_freight_charge, 2) > 0.5 THEN \'OVERCHARGED\' WHEN ROUND(billed_freight_charge - expected_freight_charge, 2) < -0.5 THEN \'UNDERCHARGED\' ELSE \'MATCHED\' END AS reconciliation_status, CASE WHEN billed_zone != expected_zone AND billed_weight_slabs_count > expected_weight_slabs_count THEN \'ZONE_AND_WEIGHT_MISMATCH\' WHEN billed_zone != expected_zone THEN \'ZONE_MISMATCH\' WHEN billed_weight_slabs_count > expected_weight_slabs_count THEN \'WEIGHT_OVERCHARGE\' WHEN ROUND(billed_freight_charge - expected_freight_charge, 2) > 0.5 THEN \'RATE_CARD_DISCREPANCY\' ELSE \'CORRECT\' END AS discrepancy_root_cause FROM contract_rate_applied;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            